<script setup lang="ts">
const route = useRoute()
const { data: product, error } = await useFetch<any>(`/api/products/${route.params.slug}`)
const reviewOrder = ref('recent'); const reviewQuery = computed(() => ({ limit: 10, sort: reviewOrder.value === 'rating' ? 'rating' : reviewOrder.value === 'photos' ? 'photos' : 'recent' })); const { data: reviewData, refresh: refreshReviews } = await useFetch<any>(`/api/products/${route.params.slug}/reviews`, { query: reviewQuery })
const { data: externalReviews } = await useFetch<any>(`/api/products/${route.params.slug}/reviews`, { query: { source: 'EXTERNA', limit: 6 } })
const cart = useCart(); const cartFeedback = useCartFeedback(); const quantity = ref(1); const selectedImage = ref(0); const lightbox = ref(false); const touchStart = ref(0); const reviewMessage = ref(''); const reviewError = ref(''); const reviewSending = ref(false); const reviewImage = ref<File | null>(null); const reviewForm = reactive({ customerName: '', rating: 5, comment: '', phone: '', orderNumber: '', recommendation: null as boolean | null })
const formatPrice = (value: number) => new Intl.NumberFormat('es-CO', { style: 'currency', currency: 'COP', maximumFractionDigits: 0 }).format(value)
if (error.value) throw createError({ statusCode: 404, statusMessage: 'Producto no encontrado' })
const images = computed(() => product.value?.images?.length ? product.value.images : [product.value?.image || '/Logo/logotip.jpg'])
const currentImage = computed(() => images.value[selectedImage.value] || images.value[0])
const addToCart = () => { for (let index = 0; index < quantity.value; index += 1) cart.add(product.value!.slug); cartFeedback.show(product.value!.name) }
useHead(() => ({ script: [{ type: 'application/ld+json', children: JSON.stringify({ '@context': 'https://schema.org', '@type': 'Product', name: product.value?.name, image: images.value, description: product.value?.description, offers: { '@type': 'Offer', priceCurrency: 'COP', price: product.value?.price, availability: 'https://schema.org/InStock' }, ...(reviewData.value?.summary?.total ? { aggregateRating: { '@type': 'AggregateRating', ratingValue: reviewData.value.summary.average, reviewCount: reviewData.value.summary.total } } : {}) }) }] }))
const selectImage = (index: number) => { selectedImage.value = index }
const nextImage = () => { selectedImage.value = (selectedImage.value + 1) % images.value.length }
const previousImage = () => { selectedImage.value = (selectedImage.value - 1 + images.value.length) % images.value.length }
const onTouchStart = (event: TouchEvent) => { touchStart.value = event.changedTouches[0]?.clientX || 0 }
const onTouchEnd = (event: TouchEvent) => { const end = event.changedTouches[0]?.clientX || 0; if (Math.abs(end - touchStart.value) > 40) end < touchStart.value ? nextImage() : previousImage() }
const stars = (rating: number) => '★'.repeat(rating) + '☆'.repeat(5 - rating)
const uploadReviewImage = async () => { if (!reviewImage.value) return ''; const body = new FormData(); body.append('image', reviewImage.value); const result = await $fetch<{ url: string }>('/api/reviews/upload', { method: 'POST', body }); return result.url }
const submitReview = async () => { reviewError.value = ''; reviewMessage.value = ''; reviewSending.value = true; try { const imageUrl = await uploadReviewImage(); await $fetch('/api/reviews', { method: 'POST', body: { slug: product.value.slug, ...reviewForm, imageUrl } }); reviewMessage.value = 'Gracias. Tu opinión quedó pendiente de moderación.'; Object.assign(reviewForm, { customerName: '', rating: 5, comment: '', phone: '', orderNumber: '', recommendation: null }); reviewImage.value = null; await refreshReviews() } catch (error: any) { reviewError.value = error?.data?.message || 'No fue posible enviar tu opinión.' } finally { reviewSending.value = false } }
</script>

<template>
  <section v-if="product" class="container product-detail"><NuxtLink to="/productos" class="back-link">← Volver al catálogo</NuxtLink><div class="detail-grid"><div class="detail-gallery"><div class="detail-image" @touchstart="onTouchStart" @touchend="onTouchEnd"><button v-if="images.length > 1" type="button" class="gallery-arrow gallery-prev" aria-label="Imagen anterior" @click="previousImage">‹</button><img :src="currentImage" :alt="`${product.name} - imagen ${selectedImage + 1}`" fetchpriority="high" @click="lightbox = true"><button v-if="images.length > 1" type="button" class="gallery-arrow gallery-next" aria-label="Siguiente imagen" @click="nextImage">›</button><span class="gallery-counter">{{ selectedImage + 1 }} / {{ images.length }}</span></div><div v-if="images.length > 1" class="gallery-thumbnails"><button v-for="(image, index) in images" :key="`${image}-${index}`" type="button" :class="{ 'is-selected': selectedImage === index }" :aria-label="`Ver imagen ${index + 1}`" @click="selectImage(index)"><img :src="image" :alt="`${product.name}, miniatura ${index + 1}`" loading="lazy"></button></div></div><div class="detail-copy"><p class="eyebrow">{{ product.category }}</p><h1>{{ product.name }}</h1><div v-if="reviewData?.summary?.total" class="detail-rating"><span>{{ stars(Math.round(reviewData.summary.average)) }}</span> <strong>{{ reviewData.summary.average.toFixed(1) }}</strong> <a href="#opiniones">({{ reviewData.summary.total }} opiniones)</a></div><p class="detail-description">{{ product.description }}</p><div v-if="product.features?.length" class="detail-features"><span v-for="feature in product.features" :key="feature">✓ {{ feature }}</span></div><div class="detail-price"><strong>{{ formatPrice(product.price) }}</strong><del v-if="product.oldPrice">{{ formatPrice(product.oldPrice) }}</del></div><p class="stock-line"><span></span> Disponible para envío</p><div class="quantity-row"><label for="quantity">Cantidad</label><div class="quantity-control"><button aria-label="Disminuir cantidad" @click="quantity = Math.max(1, quantity - 1)">−</button><span>{{ quantity }}</span><button aria-label="Aumentar cantidad" @click="quantity += 1">+</button></div></div><button class="button is-dark detail-button" @click="addToCart">Agregar al carrito <span>↗</span></button><p class="detail-note">Compra protegida · Envíos a todo Colombia</p></div></div>
    <section id="opiniones" class="product-reviews"><div class="reviews-heading"><div><p class="eyebrow">EXPERIENCIAS REALES</p><h2>Opiniones de clientes NUVIB</h2><p v-if="reviewData?.summary?.total">{{ reviewData.summary.average.toFixed(1) }} / 5 · Basado en {{ reviewData.summary.total }} reseñas</p><p v-else>Aún no hay opiniones para este producto.</p></div><div v-if="reviewData?.summary?.total" class="review-distribution"><span v-for="level in [5,4,3,2,1]" :key="level">{{ stars(level) }} <b>{{ reviewData.summary.counts[level] || 0 }}</b></span></div></div><div v-if="reviewData?.reviews?.length" class="review-list"><article v-for="review in reviewData.reviews" :key="review._id" class="review-card"><div><strong class="review-stars">{{ stars(review.rating) }}</strong><span v-if="review.verifiedPurchase" class="verified-badge">Compra verificada</span></div><p>“{{ review.comment }}”</p><footer>— {{ review.customerName }} <small>{{ new Date(review.createdAt).toLocaleDateString('es-CO') }}</small><em v-if="review.editedByAdmin">Editada por administración</em></footer><img v-if="review.imageUrl" class="review-photo" :src="review.imageUrl" alt="Foto enviada por un cliente" loading="lazy"></article></div><p v-else class="review-empty">Sé el primero en compartir tu experiencia.</p><div v-if="reviewData?.hasMore" class="review-more">Hay más opiniones disponibles en próximas cargas.</div><div v-if="externalReviews?.reviews?.length" class="external-reviews"><h3>Valoraciones de otras fuentes</h3><article v-for="review in externalReviews.reviews" :key="review._id" class="review-card"><strong class="review-stars">{{ stars(review.rating) }}</strong><span class="external-badge">Opinión externa · {{ review.sourceName }}</span><p>“{{ review.comment }}”</p><footer>— {{ review.customerName }}<a v-if="review.sourceUrl" :href="review.sourceUrl" target="_blank" rel="noopener">Ver fuente</a></footer></article></div><form class="review-form" @submit.prevent="submitReview"><h3>Comparte tu experiencia</h3><p>Las opiniones se revisan antes de publicarse. Si ingresas pedido y teléfono de un pedido entregado, podremos marcarla como compra verificada.</p><div class="form-row"><label>Nombre<input v-model="reviewForm.customerName" required></label><label>Calificación<select v-model.number="reviewForm.rating"><option v-for="level in [5,4,3,2,1]" :key="level" :value="level">{{ stars(level) }}</option></select></label></div><label>Comentario<textarea v-model="reviewForm.comment" required minlength="10" rows="4"></textarea></label><div class="form-row"><label>Pedido (opcional)<input v-model="reviewForm.orderNumber" placeholder="NV-..."></label><label>Teléfono usado en el pedido<input v-model="reviewForm.phone" placeholder="300..."></label></div><label>Foto del producto (opcional)<input type="file" accept="image/*" @change="reviewImage = ($event.target as HTMLInputElement).files?.[0] || null"></label><p v-if="reviewMessage" class="form-success">{{ reviewMessage }}</p><p v-if="reviewError" class="form-error">{{ reviewError }}</p><button class="button is-dark" :disabled="reviewSending">{{ reviewSending ? 'Enviando...' : 'Enviar opinión' }}</button></form></section>
    <div v-if="lightbox" class="image-lightbox" role="dialog" aria-modal="true" @click.self="lightbox = false"><button type="button" aria-label="Cerrar imagen" @click="lightbox = false">×</button><img :src="currentImage" :alt="product.name"></div>
  </section>
</template>
